    "helpTopicsTitle": "帮助主题",
    "helpBasics": "基础知识",
    "helpBasicsText": [
      "键盘的 Z-M 和 Q-U 行输入音符（按键位置，无论布局如何）。1 是音符切断， 是释放，十六进制数字填写音色、音量和效果列。",
      "空格切换编辑，回车播放或停止，F5 到 F8 播放歌曲、循环乐段、从光标播放和停止。",
      "在选区时，编辑和乐段菜单可进行复制、剪切、粘贴、插入、反转、移调等操作。",
      "对乐段、帧、书签等的编辑可以撤销（Ctrl+Z）；音色如同桌面版，不能撤销。模块会在你工作时保存在此浏览器中。"
    ],
    "helpMouse": "鼠标",
    "helpMouseText": [
      "单击将光标置于单元格上，拖动进行选择。在行号上，拖动选择整行，双击选中帧；双击单元格选择其通道。右键打开菜单。",
      "滚轮滚动行；按 Ctrl 可移调，按 Shift 可更改数值，同时按两者可在帧之间切换。",
      "帧列表也可以通过拖动来选择，并且可以剪切、复制和粘贴帧。右键单击可打开帧菜单。"
    ],
    "helpKeys": "按键",
    "helpKeysText": "配置 > 按键 可更改它们。浏览器会保留一些按键（Ctrl+F4，Ctrl+W...），网页无法获取。",
