    "helpTopicsTitle": "幫助主題",
    "helpBasics": "基礎知識",
    "helpBasicsText": [
      "鍵盤的 Z-M 和 Q-U 行輸入音符（按鍵位置，無論佈局如何）。1 是音符切斷， 是釋放，十六進制數字填寫音色、音量和效果列。",
      "空格切換編輯，回車播放或停止，F5 到 F8 播放歌曲、循環樂段、從光標播放和停止。",
      "在選區時，編輯和樂段菜單可進行復制、剪切、粘貼、插入、反轉、移調等操作。",
      "對樂段、幀、書籤等的編輯可以撤銷（Ctrl+Z）；音色如同桌面版，不能撤銷。模塊會在你工作時保存在此瀏覽器中。"
    ],
    "helpMouse": "鼠標",
    "helpMouseText": [
      "單擊將光標置於單元格上，拖動進行選擇。在行號上，拖動選擇整行，雙擊選中幀；雙擊單元格選擇其通道。右鍵打開菜單。",
      "滾輪滾動行；按 Ctrl 可移調，按 Shift 可更改數值，同時按兩者可在幀之間切換。",
      "影格列表也可以通過拖動來選擇，並且可以剪切、複製和粘貼幀。右鍵單擊可打開幀菜單。"
    ],
    "helpKeys": "按鍵",
    "helpKeysText": "配置 > 按鍵 可更改它們。瀏覽器會保留一些按鍵（Ctrl+F4，Ctrl+W...），網頁無法獲取。",
    "effectTableTitle": "效果表",
