    "helpTopicsTitle": "Ayuda Temas",
    "helpBasics": "Los fundamentos",
    "helpBasicsText": [
      "Las filas Z-M y Q-U del teclado introducen notas (por el lugar de la llave, sea cual sea el diseño). 1 es una nota cortada, \\ una liberación, los dígitos hex llenan el instrumento, volumen y columnas de efecto.",
      "Space toggles editing, Enter reproducciones o paradas, F5 a F8 tocar la canción, bucle el patrón, jugar desde el cursor y parar.",
      "Con una selección, los menús Editar y Pattern copiar, cortar y pegarlo, interpolar, revertir, transponer y más.",
      "Las ediciones de patrones, marcos, marcadores y así sucesivamente se pueden deshacer ( Ctrl +Z); los instrumentos, como en el escritorio, no pueden. El módulo se guarda en este navegador como usted trabaja."
    ],
    "helpMouse": "El ratón",
    "helpMouseText": [
      "Un clic pone el cursor en una celda y selecciona un arrastre. En los números de fila, un arrastre selecciona filas enteras y un doble clic en el marco; un doble clic en una celda selecciona su canal. El botón derecho abre un menú.",
      "La rueda mueve las filas; con Ctrl transpone, con Shift cambia los valores, con ambos va de marco a marco.",
      "La lista de marcos también se selecciona arrastrando y corta, copias y marcos de pasta. Su botón derecho abre el menú de marco."
    ],
    "helpKeys": "Llaves",
    "helpKeysText": "Configuración ⁇ Claves los cambia. El navegador guarda algunas teclas ( Ctrl + F4 , Ctrl +W...), que una página no puede conseguir.",
    "effectTableTitle": "Cuadro de resultados",
    "effectTableIntro": "Escriba un efecto en la columna de efecto de un patrón: su letra y dos dígitos hexadecimales (xx, o x y y).",
    "effectColumn": "Efecto",
    "effectName": "Nombre",
    "effectDescription": "¿Qué hace?",
    "effectChips": "Chips",
    "allChips": "Todos",
    "effectInfo": {
      "1": [
        "Velocidad / Tempo",
        "xx debajo del punto de división entre los dos (32 por defecto) establece la velocidad, las ticks de una fila; de él arriba, el tempo."
      ],
      "2": [
        "Salto",
        "Saltar al marco xx."
      ],
      "3": [
        "Skip",
        "Sigue en la fila xx del siguiente marco."
      ],
      "4": [
        "Halt",
        "Deja de jugar."
      ],
      "5": [
        "Cuadrícula de longitud / sobre",
        "2A03 : 00-1F establece el contador de longitud. E0-E3 cambiar el sobre del hardware."
      ],
      "6": [
        "portamento automático",
        "Diapositiva a cada nueva nota a la velocidad xx. 00 apagado."
      ],
      "8": [
        "Hardware barrer",
        "El barrido de pulso 2A03 . x es la velocidad, y la cantidad."
      ],
      "9": [
        "Barrido de hardware",
        "El barrido de pulso 2A03 . x es la velocidad, y la cantidad."
      ],
      "10": [
        "Arpegio",
        "Juega la nota, luego +x y semitonas +y, una tick cada uno."
      ],
      "11": [
        "Vibrato",
        "x es la velocidad, y la profundidad."
      ],
      "12": [
        "Tremolo",
        "x es la velocidad, y la profundidad."
      ],
      "13": [
        "Fino campo",
        "Ajusta el tono un poco. 80 es el medio."
      ],
      "14": [
        "Fecha de demora",
        "Toca la nota xx las ticks tarde."
      ],
      "15": [
        "Ajuste del DAC",
        "Establecer el contador DPCM delta a xx (00-7F)."
      ],
      "16": [
        "Portamento up",
        "Levanta el tono por xx cada tick."
      ],
      "17": [
        "Portamento abajo",
        "Baja el tono por xx cada tick."
      ],
      "18": [
        "Ciclo del ciclo de trabajo",
        "2A03 pulso: 00-03. ruido: 00 y 01 (el modo). Otros chips: sus propios ciclos de ciclo de trabajo."
      ],
      "19": [
        "Compensación de la muestra",
        "Comience la muestra DPCM en el xx veces 64th byte."
      ],
      "20": [
        "Nota diapositiva arriba",
        "x es la velocidad, y las semitonas para subir."
      ],
      "21": [
        "Nota de diapositiva abajo",
        "x es la velocidad, y las semitonas para bajar."
      ],
      "22": [
        "Tobogán de volumen",
        "Cada tick, subir el volumen por x y bajarlo por y."
      ],
      "23": [
        "Corte de nota",
        "Cortar la nota después de xx ticks (00-7F)."
      ],
      "24": [
        "Retrigger",
        "Juega la muestra DPCM de nuevo cada xx ticks. 00 para ninguno."
      ],
      "25": [
        "Volumen dilatado",
        "Después de x ticks, establecer el volumen del canal a y."
      ],
      "26": [
        "Profundidad de modulación",
        "La profundidad de modulación FDS (00-3F)."
      ],
      "27": [
        "Velocidad de modulación alta",
        "El byte alto de la velocidad de modulación FDS (00-0F). A partir de 10 hasta es la relación de la modulación automática."
      ],
      "28": [
        "Velocidad de modulación baja",
        "El byte bajo de la velocidad de modulación FDS ."
      ],
      "29": [
        "DPCM pitch",
        "Cuán rápido juega el DPCM (00-0F)."
      ],
      "30": [
        "Forma envolvente",
        "El sobre Sunsoft 5B . y es la forma (0-F), x el cambio automático del sobre. 00 lo apaga."
      ],
      "31": [
        "Envelope period high",
        "El byte alto del período envoltorio Sunsoft 5B ."
      ],
      "32": [
        "Periodo de desarrollo bajo",
        "El byte bajo del período de sobre Sunsoft 5B ."
      ],
      "33": [
        "Período de ruido",
        "El periodo de ruido Sunsoft 5B (00-1F)."
      ],
      "34": [
        "Puerto de parche personalizado",
        "Elija el registro (0-7) del parche personalizado VRC7 para escribir."
      ],
      "35": [
        "Escribir un parche personalizado",
        "Escriba xx al registro Hxx elegido del parche personalizado VRC7 ."
      ],
      "36": [
        "Delayed release",
        "Libere la nota después de las ticks xx (00-7F)."
      ],
      "37": [
        "Groove",
        "Usa groove xx."
      ],
      "38": [
        "Transposeo retrasado",
        "Los 3 bits bajos de x son las ticks a esperar, su parte superior mordió la dirección (1 es abajo), y las semitontas."
      ],
      "39": [
        "Buffer de onda",
        "Ponga la onda N163 en xx veces 2. 7F vuelve a la del instrumento."
      ],
      "40": [
        "Sobre de volumen",
        "El sobre de volumen FDS . 00-7F establece velocidad y modo, E0 lo apaga."
      ],
      "41": [
        "Sesgo de modulación",
        "El sesgo de FM automático FDS . 80 es el medio."
      ],
      "42": [
        "restablecimiento de fase",
        "Reiniciar la fase de la ola sin volver a tocar la nota."
      ],
      "43": [
        "Armonic",
        "Multiplique el lanzamiento por xx."
      ],
      "44": [
        "Objetivo tobogán de volumen",
        "x es la velocidad, y el volumen a alcanzar. 00 lo detiene."
      ]
    },
